-- 0022_cn35_user_exp_curve.sql 用户等级经验表接入：回填存量 max_exp。
-- cn35_player_profiles.max_exp 原为占位常量 100（story350-07 临时口径）；
-- 本迁移按用户等级经验表（gamerch 社区资料，数据胶囊
-- server/assets/shared/reference/user_level_exp_table.tsv，全链互证）把存量行
-- max_exp 回填为当前等级的升级需求；2100 级封顶行回退末档 need(2099)=4200000
-- （满足 0003 CHECK(max_exp>0)，与 cn35game.UserNeedExpCapped 同口径）。
-- 幂等：重放结果一致；不改 exp/level（旧口径溢出行由下次结算按真表自愈，
-- 见 notes/proposed/2026-10-01-cn35-user-exp-curve.md 风险节）。
CREATE TABLE cn35_exp_curve_stage (level INTEGER PRIMARY KEY, need_exp INTEGER NOT NULL);
UPDATE cn35_player_profiles
SET max_exp = (SELECT need_exp FROM cn35_exp_curve_stage WHERE level = cn35_player_profiles.level)
WHERE level IN (SELECT level FROM cn35_exp_curve_stage);
DROP TABLE cn35_exp_curve_stage;
